package server

import (
    "encoding/json"
    "net/http"
    "frozen-service/internal/logging"
    "os"
    "frozen-service/internal/auth"
)

func New() http.Handler {
    mux := http.NewServeMux()
    mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
        w.Header().Set("Content-Type", "application/json")
        health := logging.Status()
        if !health.Ready { w.WriteHeader(http.StatusServiceUnavailable) }
        _ = json.NewEncoder(w).Encode(map[string]any{"status":health.Status, "project":"frozen-service", "logging":health, "database":"connection not checked by health endpoint"})
    })
    mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
        if !logging.Ready() { http.Error(w,"logging unavailable",http.StatusServiceUnavailable);return }
        w.WriteHeader(http.StatusOK)
    })

    mux.Handle("GET /api/private", auth.Middleware(os.Getenv("AUTH_SECRET"), http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("authenticated")) })))
    return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){
        if r.Method!="GET" && r.Method!="HEAD" && r.Method!="OPTIONS" && !logging.Ready() { http.Error(w,"service not ready",http.StatusServiceUnavailable);return }
        mux.ServeHTTP(w,r)
    })
}

